const data = $input.first().json.output;

if (!data) return [];

// Check for critical columns
if (!data['Invoice Number'] || 
    !data['Client Name'] || 
    !data['Total'] || 
    !data['Due Date']) {

    data['Validation_Status'] = 'Failed';
    data['Error_Reason'] = 'Missing critical fields';
    return [ { json: data } ];   
}

const total = parseFloat(data['Total']) || 0;
const status = String(data['Payment Status'] || '').toLowerCase().trim();

// Skip paid or invalid amount invoices
if (total <= 0) {
    data['Validation_Status'] = 'Failed';
       return [ { json: data } ];   // → Send to Bad Log
}

// If all checks pass
data['Validation_Status'] = 'Passed';
return [ { json: data } ];

