// === REMINDER LOGIC - Handles new invoices in any aging bucket ===

const data = item.json;

const days = parseInt(data['Days Overdue']) || 0;
const stage = String(data['Follow-up Stage'] || "").trim();

let sendEmail = false;
let reminderType = null;
let newStage = null;

console.log(`Debug - Invoice ${data['Invoice Number']}: Days=${days}, Stage="${stage}"`);

// Logic for new invoices or progressing invoices
if (stage === "" || stage === "No Reminder") {
    if (days >= 25 && days <= 40) {
        sendEmail = true;
        reminderType = "Low Risk";
        newStage = "1st Reminder Sent";
    } else if (days >= 41 && days <= 70) {
        sendEmail = true;
        reminderType = "Medium Risk";
        newStage = "2nd Reminder Sent";
    } else if (days >= 71) {
        sendEmail = true;
        reminderType = "High Risk";
        newStage = "Urgent Notice Sent";
    }
} 
else if (stage === "1st Reminder Sent" && days >= 45 && days <= 70) {
    sendEmail = true;
    reminderType = "Medium Risk";
    newStage = "2nd Reminder Sent";
} 
else if (stage === "2nd Reminder Sent" && days >= 71) {
    sendEmail = true;
    reminderType = "High Risk";
    newStage = "Urgent Notice Sent";
}

data['Send_Email_Today'] = sendEmail;
data['Reminder_Type'] = reminderType;
data['New_Follow-up_Stage'] = newStage;

return item;
